import os
import hmac
import hashlib
import time
import json
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs, unquote

SECRET_KEY = os.environ.get('APP_SECRET', 'default-secret-key-change-me')
SESSION_STORE = {}
RATE_LIMIT = {}

def generate_token(user_id, timestamp):
    """Generate HMAC token for session validation."""
    msg = f"{user_id}:{timestamp}".encode('utf-8')
    return hmac.new(SECRET_KEY.encode('utf-8'), msg, hashlib.sha256).hexdigest()

def validate_token(user_id, timestamp, token):
    """Validate session token using HMAC comparison."""
    expected = generate_token(user_id, timestamp)
    return hmac.compare_digest(expected, token)

def check_rate_limit(client_ip):
    """Rate limiting: max 100 requests per minute per IP."""
    now = time.time()
    if client_ip not in RATE_LIMIT:
        RATE_LIMIT[client_ip] = []
    # Clean old entries
    RATE_LIMIT[client_ip] = [t for t in RATE_LIMIT[client_ip] if now - t < 60]
    if len(RATE_LIMIT[client_ip]) >= 100:
        return False
    RATE_LIMIT[client_ip].append(now)
    return True

def sanitize_input(value):
    """Sanitize user input to prevent injection."""
    if not isinstance(value, str):
        return ''
    # Remove null bytes
    value = value.replace('\x00', '')
    # Limit length
    return value[:1024]

def normalize_path(base_dir, user_path):
    """Safely resolve a user-provided path within base_dir."""
    # Decode percent-encoded characters
    decoded_path = unquote(user_path)
    # Remove leading slashes and normalize
    cleaned = decoded_path.lstrip('/')
    # Construct full path
    full_path = os.path.join(base_dir, cleaned)
    # Resolve to absolute path
    resolved = os.path.realpath(full_path)
    # Verify it's within base_dir
    base_resolved = os.path.realpath(base_dir)
    if resolved.startswith(base_resolved + os.sep) or resolved == base_resolved:
        return resolved
    return None

class FileRecord:
    """Represents a file record with metadata."""
    def __init__(self, filename, owner, size, permissions):
        self.filename = filename
        self.owner = owner
        self.size = size
        self.permissions = permissions
        self.created_at = time.time()

    def to_dict(self):
        return {
            'filename': self.filename,
            'owner': self.owner,
            'size': self.size,
            'permissions': self.permissions,
            'created_at': self.created_at
        }

    def check_access(self, requesting_user, operation):
        """Check if requesting_user can perform operation on this file."""
        if requesting_user == self.owner:
            return True
        if operation == 'read' and self.permissions & 0o004:
            return True
        if operation == 'write' and self.permissions & 0o002:
            return True
        return False

class DocumentStore:
    """Document storage with access control."""

    def __init__(self, storage_root):
        self.storage_root = storage_root
        self.records = {}
        self._ensure_storage()

    def _ensure_storage(self):
        os.makedirs(self.storage_root, exist_ok=True)

    def store_document(self, user_id, filename, content):
        """Store a document for a user."""
        safe_filename = sanitize_input(filename)
        if not safe_filename or '/' in safe_filename or '\\' in safe_filename:
            return {'error': 'Invalid filename'}

        # Create user directory
        user_dir = os.path.join(self.storage_root, user_id)
        os.makedirs(user_dir, exist_ok=True)

        file_path = normalize_path(user_dir, safe_filename)
        if file_path is None:
            return {'error': 'Path traversal detected'}

        with open(file_path, 'w') as f:
            f.write(content)

        record = FileRecord(safe_filename, user_id, len(content), 0o644)
        self.records[f"{user_id}/{safe_filename}"] = record
        return {'success': True, 'path': safe_filename}

    def retrieve_document(self, requesting_user, owner_id, filename):
        """Retrieve a document with access control check."""
        safe_filename = sanitize_input(filename)
        record_key = f"{owner_id}/{safe_filename}"

        if record_key not in self.records:
            return {'error': 'Document not found'}

        record = self.records[record_key]
        if not record.check_access(requesting_user, 'read'):
            return {'error': 'Access denied'}

        user_dir = os.path.join(self.storage_root, owner_id)
        file_path = normalize_path(user_dir, safe_filename)
        if file_path is None:
            return {'error': 'Invalid path'}

        with open(file_path, 'r') as f:
            content = f.read()

        return {'success': True, 'content': content, 'metadata': record.to_dict()}

    def delete_document(self, requesting_user, owner_id, filename):
        """Delete a document with access control."""
        safe_filename = sanitize_input(filename)
        record_key = f"{owner_id}/{safe_filename}"

        if record_key not in self.records:
            return {'error': 'Document not found'}

        record = self.records[record_key]
        if not record.check_access(requesting_user, 'write'):
            return {'error': 'Access denied'}

        user_dir = os.path.join(self.storage_root, owner_id)
        file_path = normalize_path(user_dir, safe_filename)
        if file_path is None:
            return {'error': 'Invalid path'}

        os.remove(file_path)
        del self.records[record_key]
        return {'success': True}

    def list_documents(self, requesting_user, owner_id):
        """List documents accessible to requesting_user."""
        results = []
        prefix = f"{owner_id}/"
        for key, record in self.records.items():
            if key.startswith(prefix):
                if record.check_access(requesting_user, 'read'):
                    results.append(record.to_dict())
        return {'success': True, 'documents': results}

    def share_document(self, owner_id, filename, target_permissions):
        """Update permissions to share a document."""
        safe_filename = sanitize_input(filename)
        record_key = f"{owner_id}/{safe_filename}"

        if record_key not in self.records:
            return {'error': 'Document not found'}

        record = self.records[record_key]
        # Only owner can share
        record.permissions = target_permissions
        return {'success': True}


class RequestHandler(BaseHTTPRequestHandler):
    document_store = DocumentStore('/tmp/docstore')

    def do_GET(self):
        if not check_rate_limit(self.client_address[0]):
            self.send_error(429, 'Rate limit exceeded')
            return

        parsed = urlparse(self.path)
        path = parsed.path
        params = parse_qs(parsed.query)

        if path == '/api/documents':
            self._handle_list(params)
        elif path == '/api/document':
            self._handle_retrieve(params)
        elif path == '/api/health':
            self._send_json({'status': 'ok'})
        else:
            self.send_error(404)

    def do_POST(self):
        if not check_rate_limit(self.client_address[0]):
            self.send_error(429, 'Rate limit exceeded')
            return

        parsed = urlparse(self.path)
        path = parsed.path

        content_length = int(self.headers.get('Content-Length', 0))
        if content_length > 10 * 1024 * 1024:  # 10MB limit
            self.send_error(413, 'Request too large')
            return

        body = self.rfile.read(content_length)

        try:
            data = json.loads(body)
        except json.JSONDecodeError:
            self.send_error(400, 'Invalid JSON')
            return

        if path == '/api/document':
            self._handle_store(data)
        elif path == '/api/document/delete':
            self._handle_delete(data)
        elif path == '/api/document/share':
            self._handle_share(data)
        else:
            self.send_error(404)

    def _authenticate(self, params=None, data=None):
        """Authenticate request and return user_id."""
        auth_header = self.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return None

        token_parts = auth_header[7:].split(':')
        if len(token_parts) != 3:
            return None

        user_id, timestamp, token = token_parts

        # Check token age (max 1 hour)
        try:
            ts = int(timestamp)
        except ValueError:
            return None

        if abs(time.time() - ts) > 3600:
            return None

        if validate_token(user_id, timestamp, token):
            return user_id
        return None

    def _handle_list(self, params):
        user_id = self._authenticate(params=params)
        if not user_id:
            self.send_error(401, 'Unauthorized')
            return

        owner = params.get('owner', [user_id])[0]
        result = self.document_store.list_documents(user_id, owner)
        self._send_json(result)

    def _handle_retrieve(self, params):
        user_id = self._authenticate(params=params)
        if not user_id:
            self.send_error(401, 'Unauthorized')
            return

        owner = params.get('owner', [None])[0]
        filename = params.get('filename', [None])[0]
        if not owner or not filename:
            self.send_error(400, 'Missing parameters')
            return

        result = self.document_store.retrieve_document(user_id, owner, filename)
        if 'error' in result:
            self.send_error(403, result['error'])
        else:
            self._send_json(result)

    def _handle_store(self, data):
        user_id = self._authenticate(data=data)
        if not user_id:
            self.send_error(401, 'Unauthorized')
            return

        filename = data.get('filename')
        content = data.get('content')
        if not filename or content is None:
            self.send_error(400, 'Missing filename or content')
            return

        result = self.document_store.store_document(user_id, filename, content)
        if 'error' in result:
            self.send_error(400, result['error'])
        else:
            self._send_json(result)

    def _handle_delete(self, data):
        user_id = self._authenticate(data=data)
        if not user_id:
            self.send_error(401, 'Unauthorized')
            return

        owner = data.get('owner', user_id)
        filename = data.get('filename')
        if not filename:
            self.send_error(400, 'Missing filename')
            return

        result = self.document_store.delete_document(user_id, owner, filename)
        if 'error' in result:
            self.send_error(403, result['error'])
        else:
            self._send_json(result)

    def _handle_share(self, data):
        user_id = self._authenticate(data=data)
        if not user_id:
            self.send_error(401, 'Unauthorized')
            return

        filename = data.get('filename')
        permissions = data.get('permissions', 0o644)
        if not filename:
            self.send_error(400, 'Missing filename')
            return

        result = self.document_store.share_document(user_id, filename, permissions)
        if 'error' in result:
            self.send_error(400, result['error'])
        else:
            self._send_json(result)

    def _send_json(self, data):
        response = json.dumps(data).encode('utf-8')
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(response)))
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.end_headers()
        self.wfile.write(response)


if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), RequestHandler)
    print('Server starting on port 8080')
    server.serve_forever()
